// Medical Innovation lessons 1–5: the event, finding a need, originality and patents, designing the innovation,
// and prototyping and testing.
const RULES=['HOSA Medical Innovation 2026–27 guidelines and rating sheets','https://hosa.org/wp-content/uploads/2026/09/MI-26-27-9.25.pdf'];
const IDEO=['IDEO: design thinking','https://designthinking.ideo.com/'];
const USPTO=['USPTO: search for patents','https://www.uspto.gov/patents/search'];
const EPO=['European Patent Office: Espacenet patent search','https://worldwide.espacenet.com/'];
const HF=['AHRQ PSNet: human factors engineering','https://psnet.ahrq.gov/primer/human-factors-engineering'];
